input.script:
var articles = document.querySelectorAll("article");
var results = [];
articles.forEach(function(el) {
  var header = el.querySelector("header");
  var name = header ? header.getAttribute("title") : null;
  var div = el.querySelector("div");
  var text = div ? div.textContent.trim() : null;
  results.push({name: name, info: text});
});
return results;
